export function periodMonths(months,mode,key){return months.filter(m=>mode==='lifetime'||(m.key<=key&&(mode==='ytd'?m.key.slice(0,4)===key.slice(0,4):m.key===key))).sort((a,b)=>a.key.localeCompare(b.key))}
export function aggregateUnits(months){const units=new Map();for(const m of months)for(const u of m.units){const id=u.address+'|'+u.unit;const prior=units.get(id)||{...u,rent:0,paid:0};units.set(id,{...u,rent:Math.round((prior.rent+u.rent)*100)/100,paid:Math.round((prior.paid+u.paid)*100)/100});}return [...units.values()]}
// Expense filters use the recorded date or service-period end, never an inferred cash date.
export function expenseMonth(date){const s=String(date||'').trim();const simple=s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);if(simple&&+simple[1]>=1&&+simple[1]<=12&&+simple[2]>=1&&+simple[2]<=31)return simple[3]+'-'+simple[1].padStart(2,'0');const end=s.match(/[-–]\s*(\d{1,2})\/(\d{1,2})\/(\d{4})$/);if(end&&+end[1]<=12&&+end[2]<=31)return end[3]+'-'+end[1].padStart(2,'0');const named=s.match(/[-–]\s*([A-Za-z]{3})\s+\d{1,2},?\s+(\d{4})$/);const names=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];if(named&&names.includes(named[1]))return named[2]+'-'+String(names.indexOf(named[1])+1).padStart(2,'0');return null;}
export function inPeriod(key,mode,through){return !!key&&(mode==='lifetime'||(key<=through&&(mode==='ytd'?key.slice(0,4)===through.slice(0,4):key===through)))}
